package com.bank.history.dto;

import com.bank.history.model.Transaction;
import java.util.List;

// Cursor response: data plus the opaque marker for the next request.
public class CursorPageResponse {
    private final List<Transaction> content;
    private final Long nextCursor;
    private final boolean hasNext;

    public CursorPageResponse(List<Transaction> content, Long nextCursor, boolean hasNext) {
        this.content = content;
        this.nextCursor = nextCursor;
        this.hasNext = hasNext;
    }
    public List<Transaction> getContent() { return content; }
    public Long getNextCursor() { return nextCursor; }
    public boolean isHasNext() { return hasNext; }
}
