package com.bank.history.service;

import com.bank.history.dto.CursorPageResponse;
import com.bank.history.model.Transaction;
import com.bank.history.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class TransactionService {

    private static final Logger log = LoggerFactory.getLogger(TransactionService.class);
    private static final int MAX_SIZE = 100;   // cap to protect the server
    private final TransactionRepository repo;

    public TransactionService(TransactionRepository repo) { this.repo = repo; }

    // Offset — good for admin screens that jump to a page and show total pages.
    public Page<Transaction> offsetPage(String accountId, int page, int size) {
        int capped = Math.min(size, MAX_SIZE);
        Pageable pageable = PageRequest.of(page, capped, Sort.by("id").descending());
        return repo.findByAccountId(accountId, pageable);
    }

    // Cursor — fast at any depth, stable under concurrent inserts.
    public CursorPageResponse cursorPage(String accountId, Long after, int limit) {
        int capped = Math.min(limit, MAX_SIZE);
        // Fetch one extra row to know if there is a next page.
        List<Transaction> rows = repo.findKeyset(accountId, after,
                PageRequest.of(0, capped + 1));
        boolean hasNext = rows.size() > capped;
        List<Transaction> content = hasNext ? rows.subList(0, capped) : rows;
        Long nextCursor = content.isEmpty() ? null
                : content.get(content.size() - 1).getId();
        log.info("Cursor page: account={} after={} returned={} hasNext={}",
                accountId, after, content.size(), hasNext);
        return new CursorPageResponse(content, nextCursor, hasNext);
    }
}
