package com.bank.history.controller;

import com.bank.history.dto.CursorPageResponse;
import com.bank.history.model.Transaction;
import com.bank.history.service.TransactionService;
import org.springframework.data.domain.Page;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/accounts/{accountId}/transactions")
public class TransactionController {

    private final TransactionService service;

    public TransactionController(TransactionService service) { this.service = service; }

    // Offset: ?page=2000&size=20 — simple, supports jump-to-page.
    @GetMapping("/offset")
    public Page<Transaction> offset(@PathVariable String accountId,
                                    @RequestParam(defaultValue = "0") int page,
                                    @RequestParam(defaultValue = "20") int size) {
        return service.offsetPage(accountId, page, size);
    }

    // Cursor: ?after=39980&limit=20 — fast at any depth, stable.
    @GetMapping("/cursor")
    public CursorPageResponse cursor(@PathVariable String accountId,
                                     @RequestParam(required = false) Long after,
                                     @RequestParam(defaultValue = "20") int limit) {
        return service.cursorPage(accountId, after, limit);
    }
}
